    @catch_interface_exception
    @lookup_handler.implicit_lookup
    def collect_snapshot(self, skip_session_renewal=False, renewal_password='Nokia@123',
                         snapshot_waiting_timeout=1200, coam=None):

        """
        Keyword for clicking 'Collect Snapshot' button and download snapshot file in 'Snapshot' page

        :param skip_session_renewal: boolean, if True, session renewal checkbox is clicked
                                     before snapshot collection
        :param renewal_password: str, password for session renewal, default is 'Nokia@123'
        :param snapshot_waiting_timeout: int, time to wait snapshot collection finished, including download time,
                                         default is 1200 second
        :param Coam coam:  str, (optional) alias that the new coam vdu object will be identified by
                           If not specified, default alias is used: "None"

        :return: str, if snapshot collection finished successfully,
                      if save location is 'Local', return snapshot file's local download dir
                      if save location is 'Remote', return snapshot collection success status
                      if snapshot collection failed, return snapshot failure status
        """
        start_time = time.time()
        status = coam.diagnostic.open_page_and_get_instance('Snapshot').collect_snapshot(
            skip_session_renewal, renewal_password, int(snapshot_waiting_timeout))
        if status == "Local snapshot collected successfully":
            return self.downloader.download(download_dir=self.download_dir, start_downloading_time=start_time)
        else:
            return status

