    @catch_interface_exception
    @lookup_handler.implicit_lookup
    def save_current_alarms(self, alarm_filter=None, coam=None):
        """
        Keyword for saving current alarms file

        :param alarm_filter: str, alarm filter
        :param Coam coam:  str, (optional) alias that the new coam vdu object will be identified by
                           If not specified, default alias is used: "None"

        :return: str, path of file or string says "No Alarm found" if alarms are present
        """
        status = coam.alarms.open_page_and_get_instance('Active Alarms').save_current_alarms(alarm_filter)
        if status == "Saved Alarm successfully":
            start_time = time.time()
            return self.downloader.download(download_dir=self.download_dir, start_downloading_time=start_time)
        else:
            return status

