    @catch_interface_exception
    @lookup_handler.implicit_lookup
    def save_fault_toggling_history(self, alarm_state=None, fault_id=None, fault_name=None, fault_source=None,
                                    node_id=None,
                                    timeout=60, coam=None):
        """
        Keyword for saving fault toggle alarm file

        :param alarm_state: str, State of the alarm
        :param fault_id: str, id of the  fault toggle alarm
        :param fault_name: str, Name of the fault toggle alarm
        :param fault_source: str, Source of the fault toggle alarm
        :param node_id: str, node id in which fault toggle alarm is present
        :param timeout: int, time to wait get alarm info, default is 60 second
        :param Coam coam:  str, (optional) alias that the new coam vdu object will be identified by
                           If not specified, default alias is used: "None"

        :return: str, path of fault toggle alarm file or string says "No Alarm found" if alarms are present
        """
        start_time = time.time()
        status = coam.alarms.open_page_and_get_instance('Fault Toggling History').save_fault_toggling_history(
            alarm_state, fault_id, fault_name, fault_source, node_id, int(timeout))
        if status == "Saved Alarm successfully":
            return self.downloader.download(download_dir=self.download_dir, start_downloading_time=start_time)
        else:
            return status

